256	    /**
257	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
258	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
259	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
260	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
261	     *
262	     * @param city     the owner's city
263	     * @param lastName the owner's last name
264	     * @return the assigned customer code
265	     */
266	    private String nextCustomerCode(String city, String lastName) {
267	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
268	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
269	        int sequence = countOwnersInCity(city) + 1;
270	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
271	    }
272	
273	    /**
274	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
275	     * owner's city already contains this many owners.
276	     */
277	    private static final int CITY_CAPACITY = 50;
278	
279	    /**
280	     * The maximum number of owners that may be created on a single day. A create is rejected with
281	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
282	     * {@code registrationDate}.
283	     */
284	    private static final int DAILY_CREATE_LIMIT = 100;
285	
286	    /**
287	     * The number of owners that must already have been created for the current day before a new
288	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
289	     * owners already carry today's {@code registrationDate}.
290	     */
291	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
292	
293	    /**
294	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
295	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
296	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
297	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
298	     * falls on a business day.
299	     *
300	     * @param date the effective registration date
301	     * @return the same date when it is a weekday, otherwise the following Monday
302	     */
303	    private static LocalDate rollToBusinessDay(LocalDate date) {
304	        return switch (date.getDayOfWeek()) {
305	            case SATURDAY -> date.plusDays(2);
306	            case SUNDAY -> date.plusDays(1);
307	            default -> date;
308	        };
309	    }
310	
311	    /**
312	     * Counts the existing owners whose {@code registrationDate} equals the given (already
313	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
314	     * business day. Called before a new owner is saved, so the returned value reflects the number of
315	     * owners created for that day prior to this create.
316	     *
317	     * @param date the adjusted business-day registration date to count against
318	     * @return the number of existing owners registered on that date
319	     */
320	    private int countOwnersRegisteredOn(LocalDate date) {
321	        return (int) this.clinicService.findAllOwners().stream()
322	            .filter(existing -> date.equals(existing.getRegistrationDate()))
323	            .count();
324	    }
325	
326	    /**
327	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
328	     *
329	     * @param city the city to count owners for
330	     * @return the number of existing owners in that city
331	     */
332	    private int countOwnersInCity(String city) {
333	        return (int) this.clinicService.findAllOwners().stream()
334	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
335	            .count();
336	    }
337	
338	    /**
339	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
340	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
341	     *
342	     * @param customerCode     the owner's assigned customer code
343	     * @param registrationDate the owner's registration date
344	     * @return the assigned membership number
345	     */
346	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
347	        String yy = String.format("%02d", registrationDate.getYear() % 100);
348	        return String.format("%s-M%s", customerCode, yy);
349	    }
